var hdrpLit = UnityEngine.Shader.Find("HDRP/Lit");
if (hdrpLit == null) return "HDRP/Lit missing";
var GltfName = "Shader Graphs/glTF-pbrMetallicRoughness";
var targets = new System.Collections.Generic.List<UnityEngine.Material>();
var seen = new System.Collections.Generic.HashSet<int>();
var guids = UnityEditor.AssetDatabase.FindAssets("t:Material");
foreach (var g in guids) {
  var path = UnityEditor.AssetDatabase.GUIDToAssetPath(g);
  if (string.IsNullOrEmpty(path)) continue;
  if (path.StartsWith("Packages/", System.StringComparison.OrdinalIgnoreCase)) continue;
  var assets = UnityEditor.AssetDatabase.LoadAllAssetsAtPath(path);
  if (assets == null || assets.Length == 0) {
    var single = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>(path);
    if (single != null && single.shader != null && single.shader.name == GltfName && seen.Add(single.GetInstanceID()))
      targets.Add(single);
    continue;
  }
  foreach (var a in assets) {
    var mat = a as UnityEngine.Material;
    if (mat == null || mat.shader == null) continue;
    if (mat.shader.name != GltfName) continue;
    if (!seen.Add(mat.GetInstanceID())) continue;
    targets.Add(mat);
  }
}
int converted = 0; int failed = 0;
var lines = new System.Collections.Generic.List<string>();
UnityEditor.AssetDatabase.StartAssetEditing();
try {
  foreach (var mat in targets) {
    try {
      var path = UnityEditor.AssetDatabase.GetAssetPath(mat);
      var baseColor = mat.HasProperty("baseColorFactor") ? mat.GetColor("baseColorFactor") : UnityEngine.Color.white;
      var baseMap = mat.HasProperty("baseColorTexture") ? mat.GetTexture("baseColorTexture") : null;
      var baseScale = (baseMap != null && mat.HasProperty("baseColorTexture")) ? mat.GetTextureScale("baseColorTexture") : UnityEngine.Vector2.one;
      var baseOffset = (baseMap != null && mat.HasProperty("baseColorTexture")) ? mat.GetTextureOffset("baseColorTexture") : UnityEngine.Vector2.zero;
      var normalMap = mat.HasProperty("normalTexture") ? mat.GetTexture("normalTexture") : null;
      var normalScale = mat.HasProperty("normalTexture_scale") ? mat.GetFloat("normalTexture_scale") : 1f;
      var metallic = mat.HasProperty("metallicFactor") ? mat.GetFloat("metallicFactor") : 0f;
      var roughness = mat.HasProperty("roughnessFactor") ? mat.GetFloat("roughnessFactor") : 1f;
      var smoothness = 1f - UnityEngine.Mathf.Clamp01(roughness);
      var emissive = mat.HasProperty("emissiveFactor") ? mat.GetColor("emissiveFactor") : UnityEngine.Color.black;
      var emissiveMap = mat.HasProperty("emissiveTexture") ? mat.GetTexture("emissiveTexture") : null;
      var hasEmission = mat.IsKeywordEnabled("_EMISSIVE") || emissiveMap != null || emissive.maxColorComponent > 0.0001f;
      var alphaCutoff = mat.HasProperty("alphaCutoff") ? mat.GetFloat("alphaCutoff") : 0.5f;
      var alphaClip = mat.HasProperty("_AlphaCutoffEnable") && mat.GetFloat("_AlphaCutoffEnable") > 0.5f;
      var transparent = mat.HasProperty("_SurfaceType") && mat.GetFloat("_SurfaceType") > 0.5f;
      var doubleSided = mat.HasProperty("_DoubleSidedEnable") && mat.GetFloat("_DoubleSidedEnable") > 0.5f;
      mat.shader = hdrpLit;
      if (baseMap != null) { mat.SetTexture("_BaseColorMap", baseMap); mat.SetTextureScale("_BaseColorMap", baseScale); mat.SetTextureOffset("_BaseColorMap", baseOffset); }
      mat.SetColor("_BaseColor", baseColor);
      if (normalMap != null) { mat.SetTexture("_NormalMap", normalMap); mat.SetFloat("_NormalScale", normalScale); mat.SetFloat("_NormalMapSpace", 0f); }
      mat.SetFloat("_Metallic", metallic);
      mat.SetFloat("_Smoothness", smoothness);
      if (hasEmission) {
        if (emissiveMap != null) mat.SetTexture("_EmissiveColorMap", emissiveMap);
        UnityEditor.Rendering.HighDefinition.HDMaterial.SetUseEmissiveIntensity(mat, false);
        UnityEditor.Rendering.HighDefinition.HDMaterial.SetEmissiveColor(mat, emissive);
      }
      if (alphaClip) {
        UnityEditor.Rendering.HighDefinition.HDMaterial.SetAlphaClipping(mat, true);
        UnityEditor.Rendering.HighDefinition.HDMaterial.SetAlphaCutoff(mat, alphaCutoff);
      }
      UnityEditor.Rendering.HighDefinition.HDMaterial.SetSurfaceType(mat, transparent);
      if (doubleSided) UnityEditor.Rendering.HighDefinition.HDMaterial.SetDoubleSided(mat, true);
      UnityEditor.Rendering.HighDefinition.HDMaterial.ValidateMaterial(mat);
      UnityEditor.EditorUtility.SetDirty(mat);
      converted++;
      lines.Add(path + " :: " + mat.name);
    } catch (System.Exception ex) { failed++; lines.Add("FAIL " + mat.name + ": " + ex.Message); }
  }
} finally {
  UnityEditor.AssetDatabase.StopAssetEditing();
  UnityEditor.AssetDatabase.SaveAssets();
}
// verify remaining
int remain = 0;
foreach (var g in UnityEditor.AssetDatabase.FindAssets("t:Material")) {
