private void ProcessReloadKey()
{
    if (!GameSession.HasStarted || Time.timeScale <= 0f)
    {
        CancelHold();
        return;
    }

    if (playerController != null && playerController.BlocksCombatInput)
    {
        CancelHold();
        return;
    }

    Keyboard keyboard = Keyboard.current;
    if (keyboard == null)
        return;

    if (keyboard.rKey.wasPressedThisFrame)
    {
        holdingReload = true;
        openedMenuThisHold = false;
        holdStartUnscaled = Time.unscaledTime;
    }

    if (!holdingReload)
        return;

    float held = Time.unscaledTime - holdStartUnscaled;
    if (!openedMenuThisHold && held >= HoldSecondsToOpen)
    {
        openedMenuThisHold = true;
        OpenModeSwitchMenu();
    }

    if (!keyboard.rKey.wasReleasedThisFrame)
        return;

    holdingReload = false;
    if (!openedMenuThisHold && held <= MaxReloadTapSeconds)
        TryReload();

    openedMenuThisHold = false;
}

private void CancelHold()
{
    holdingReload = false;
    openedMenuThisHold = false;
}

private void TryReload()
{
    if (bootstrap == null || !bootstrap.IsActive)
        return;

    PioneerInvectorAmmoBridge ammoBridge = GetComponent<PioneerInvectorAmmoBridge>();
    if (ammoBridge != null && !ammoBridge.TryRequestReload(playEmptyDenyFeedback: true))
        return;

    if (bootstrap.ShooterManager != null)
        bootstrap.ShooterManager.ReloadWeapon();
}

