private void RebuildVisibleDotSet()
{
    visiblePickupScratch.Clear();
    visibleHarvestScratch.Clear();
    candidateScratch.Clear();
    primaryNearPickup = null;
    primaryNearHarvest = null;

    float nearR = Mathf.Max(0.5f, nearExclusiveRadius);
    float farR = Mathf.Max(nearR, farVisibilityRadius);
    float nearSqr = nearR * nearR;
    float farSqr = farR * farR;
    float cosFov = Mathf.Cos(farFovHalfAngleDegrees * Mathf.Deg2Rad);
    Vector3 camPos = worldCamera.transform.position;
    Vector3 camFwd = worldCamera.transform.forward;

    foreach (ItemPickup pickup in trackedPickups)
    {
        if (!IsPickupTrackable(pickup) || pickup.IsPickedUp || pickup.itemData == null)
            continue;

        Vector3 pos = pickup.transform.position;
        float sqr = (pos - playerTransform.position).sqrMagnitude;
        if (sqr > farSqr)
            continue;

        candidateScratch.Add(new DotCandidate
        {
            Pickup = pickup,
            WorldPos = pos,
            Distance = Mathf.Sqrt(sqr),
            IsNear = sqr <= nearSqr
        });
    }

    foreach (ResourceNode node in trackedHarvestNodes)
    {
        if (node == null
            || node.interactionMode != ResourceNodeInteractionMode.HoldHarvest
            || node.resourceItem == null
            || node.IsHoldActive)
        {
            continue;
        }

        Vector3 pos = node.GetNodeCenter();
        float sqr = (pos - playerTransform.position).sqrMagnitude;
        if (sqr > farSqr)
            continue;

        candidateScratch.Add(new DotCandidate
        {
            Harvest = node,
            WorldPos = pos,
            Distance = Mathf.Sqrt(sqr),
            IsNear = sqr <= nearSqr
        });
    }

    if (candidateScratch.Count == 0)
        return;

    candidateScratch.Sort((a, b) => a.Distance.CompareTo(b.Distance));

    // Close cluster: only the single nearest pickup/harvest marker.
    for (int i = 0; i < candidateScratch.Count; i++)
    {
        if (!candidateScratch[i].IsNear)
            continue;

        AcceptCandidate(candidateScratch[i]);
        primaryNearPickup = candidateScratch[i].Pickup;
        primaryNearHarvest = candidateScratch[i].Harvest;
        return;
    }

    int accepted = 0;
    for (int i = 0; i < candidateScratch.Count && accepted < maxFarVisibleDots; i++)
    {
        DotCandidate c = candidateScratch[i];
        Vector3 to = (c.WorldPos + Vector3.up * verticalWorldOffset) - camPos;
        float dist = to.magnitude;
        if (dist < 0.05f)
            continue;

        Vector3 dir = to / dist;
        if (Vector3.Dot(camFwd, dir) < cosFov)
            continue;

        if (!HasLineOfSight(camPos, c.WorldPos + Vector3.up * verticalWorldOffset))
            continue;

        AcceptCandidate(c);
        accepted++;
    }
}

