private void ApplyMouseWheelZoom()
{
    float raw = Mouse.current.scroll.ReadValue().y;
    if (Mathf.Abs(raw) < 0.01f)
        return;

    // Accumulate fractional wheel deltas into whole notches so one tick = one zoom step.
    _scrollNotchAccumulator += raw / ScrollUnitsPerNotch;
    int notches = 0;
    if (Mathf.Abs(_scrollNotchAccumulator) >= 0.35f)
    {
        notches = _scrollNotchAccumulator > 0f
            ? Mathf.Max(1, Mathf.RoundToInt(_scrollNotchAccumulator))
            : Mathf.Min(-1, Mathf.RoundToInt(_scrollNotchAccumulator));
        _scrollNotchAccumulator -= notches;
    }

    if (notches == 0)
        return;

    float step = (runtimeMaxCameraDistance - runtimeMinCameraDistance) / ScrollNotchesFullRange;
    float current = tpCamera.CurrentZoom > 0.01f ? tpCamera.CurrentZoom : GetPreferredZoom();
    float next = Mathf.Clamp(
        current - notches * step,
        runtimeMinCameraDistance,
        runtimeMaxCameraDistance);
    tpCamera.ForceSetZoomDistance(next);
    _preferredCameraZoom = next;
    _lockedAimZoom = -1f;
}

