private static bool IsInsideForwardCone(
    Vector3 origin,
    Vector3 forward,
    Vector3 worldPos,
    float halfAngleDegrees)
{
    Vector3 toTarget = worldPos - origin;
    if (toTarget.sqrMagnitude < 0.0001f)
        return true;

    return Vector3.Angle(forward, toTarget) <= halfAngleDegrees;
}

