using Project.Core;
using UnityEngine;

namespace Project.CameraFx
{
    /// <summary>
    /// Applies trauma shake to the gameplay camera.
    ///
    /// HDRP (and modern SRPs) often ignore transform edits inside
    /// <c>beginCameraRendering</c> because view matrices are already captured.
    /// Invector also poses the parent <c>vThirdPersonCamera</c> in FixedUpdate via
    /// Rigidbody.MovePosition — so we shake this Camera child's <b>local</b>
    /// transform in LateUpdate, which survives the parent rig move and is picked
    /// up at render time.
    /// </summary>
    [DisallowMultipleComponent]
    [RequireComponent(typeof(Camera))]
    [DefaultExecutionOrder(32000)]
    public class CameraShakeListener : MonoBehaviour
    {
        [SerializeField] private bool activateOnEnable = true;

        private Camera _camera;
        private bool _shakeActive;
        private Vector3 _baselineLocalPosition;
        private Quaternion _baselineLocalRotation = Quaternion.identity;
        private bool _baselineCaptured;

        /// <summary>Peak |local position offset| from the most recent sample (debug).</summary>
        public float DebugLastAppliedPositionMagnitude { get; private set; }

        public static CameraShakeListener EnsureOn(Camera camera)
        {
            if (camera == null)
                return null;

            CameraShakeService.EnsureExists();

            CameraShakeListener listener = camera.GetComponent<CameraShakeListener>();
            if (listener == null)
                listener = camera.gameObject.AddComponent<CameraShakeListener>();

            listener._camera = camera;
            listener.Activate();
            return listener;
        }

        private void Awake()
        {
            if (_camera == null)
                _camera = GetComponent<Camera>();
            CaptureBaselineLocalPose();
        }

        private void OnEnable()
        {
            CaptureBaselineLocalPose();
            if (activateOnEnable)
                Activate();
        }

        private void OnDisable()
        {
            RestoreBaselineLocalPose();
            if (CameraShakeService.Instance != null)
                CameraShakeService.Instance.ClearActiveListener(this);
            _shakeActive = false;
        }

        public void Activate()
        {
            CameraShakeService service = CameraShakeService.EnsureExists();
            if (service == null)
                return;

            if (_camera == null)
                _camera = GetComponent<Camera>();

            CaptureBaselineLocalPose();
            service.SetActiveListener(this);
            _shakeActive = true;
        }

        public void SetActiveForShake(bool active)
        {
            if (!active)
                RestoreBaselineLocalPose();

            _shakeActive = active;
        }

        private void LateUpdate()
        {
            if (!_shakeActive || _camera == null || !_camera.enabled || !isActiveAndEnabled)
            {
                RestoreBaselineLocalPose();
                return;
            }

            CameraShakeService service = CameraShakeService.Instance;
            if (service == null || service.ActiveListener != this)
            {
                RestoreBaselineLocalPose();
                return;
            }

            if (!_baselineCaptured)
                CaptureBaselineLocalPose();

            service.SampleShake(out Vector3 positionOffset, out Vector3 eulerOffset);
            DebugLastAppliedPositionMagnitude = positionOffset.magnitude;

            // Local offsets on the Camera child — parent Invector rig keeps world follow.
            transform.localPosition = _baselineLocalPosition + positionOffset;
            transform.localRotation = _baselineLocalRotation * Quaternion.Euler(eulerOffset);
        }

        private void CaptureBaselineLocalPose()
        {
            // Only capture a rest pose when we are not currently displaced by shake.
            if (_baselineCaptured)
                return;

            _baselineLocalPosition = transform.localPosition;
            _baselineLocalRotation = transform.localRotation;
            _baselineCaptured = true;
        }

        private void RestoreBaselineLocalPose()
        {
            if (!_baselineCaptured)
                return;

            transform.localPosition = _baselineLocalPosition;
            transform.localRotation = _baselineLocalRotation;
        }
    }
}

