/// <summary>
/// Current shake strength (trauma squared) for listeners.
/// Includes same-frame <see cref="SustainTrauma"/> so LateUpdate listeners
/// feel continuous rumble even when Service.Update already cleared the sustain slot.
/// </summary>
public float GetShakeStrength()
{
    float held = Mathf.Max(_trauma, Mathf.Clamp01(_sustainedTrauma));
    float t = Mathf.Clamp01(held);
    return t * t * Mathf.Max(0f, globalIntensity);
}

